    public override IList<object> parseOHLCV(object ohlcv, object market = null)
    {
        //
        // spot:
        //
        //     [
        //         [
        //             "22814.01",
        //             "22937.42",
        //             "22832.57",
        //             "22937.42",
        //             "3916.58764051",
        //             "0.171199",
        //             "2982.64647063",
        //             "0.130295",
        //             33,
        //             0,
        //             "22877.449915304470460711",
        //             "MINUTE_5",
        //             1659664800000,
        //             1659665099999
        //         ]
        //     ]
        //
        // contract:
        //
        //           [
        //             "84207.02",
        //             "84320.85",
        //             "84207.02",
        //             "84253.83",
        //             "3707.5395",
        //             "44",
        //             "14",
        //             "1740770040000",
        //             "1740770099999",
        //           ],
        //
        int ohlcvLength = getArrayLength(ohlcv);
        bool isContract = (ohlcvLength == 9);
        if (isContract)
        {
            return new List<object> {this.safeInteger(ohlcv, 7), this.safeNumber(ohlcv, 2), this.safeNumber(ohlcv, 1), this.safeNumber(ohlcv, 0), this.safeNumber(ohlcv, 3), this.safeNumber(ohlcv, 5)};
        }
        return new List<object> {this.safeInteger(ohlcv, 12), this.safeNumber(ohlcv, 2), this.safeNumber(ohlcv, 1), this.safeNumber(ohlcv, 0), this.safeNumber(ohlcv, 3), this.safeNumber(ohlcv, 5)};
    }

    /**
     * @method
     * @name poloniex#fetchOHLCV
     * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
     * @see https://api-docs.poloniex.com/spot/api/public/market-data#candles
     * @see https://api-docs.poloniex.com/v3/futures/api/market/get-kline-data
     * @param {string} symbol unified symbol of the market to fetch OHLCV data for
     * @param {string} timeframe the length of time each candle represents
     * @param {int} [since] timestamp in ms of the earliest candle to fetch
     * @param {int} [limit] the maximum amount of candles to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] timestamp in ms
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
     */
    public async override Task<List<ccxt.OHLCV>> FetchOHLCV(string symbol, string timeframe = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        string timeframeVar = timeframe;
        timeframeVar ??= "1m";
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        bool? paginate = false;
        IList<object> paginateparametersVariable = (IList<object>)this.handleOptionBoolAndParams(parameters, "fetchOHLCV", "paginate", false);
        paginate = (bool?)paginateparametersVariable[0];
        parameters = paginateparametersVariable[1];
        if ((paginate == true))
        {
            return ccxt.BaseExchange.ToOHLCVList(await this.fetchPaginatedCallDeterministic("fetchOHLCV", symbol, since, limit,timeframeVar, parameters, 500));
        }
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "symbol", (market.ContainsKey("id") ? market["id"] : null) },
            { "interval", this.safeString(this.timeframes, timeframeVar, timeframeVar) },
        };
        string keyStart = "sTime";
        if ((((market.ContainsKey("spot") ? market["spot"] : null) as bool?) == true))
        {
            keyStart = "startTime";
        }
        string keyEnd = "eTime";
        if ((((market.ContainsKey("spot") ? market["spot"] : null) as bool?) == true))
        {
            keyEnd = "endTime";
        }
        if ((since != null))
        {
            request[(string)keyStart] = since;
        }
        if ((limit != null))
        {
            // limit should in between 100 and 500
            request["limit"] = limit;
        }
        IList<object> requestparametersVariable = (IList<object>)this.handleUntilOption(keyEnd, request, parameters);
        request = (Dictionary<string, object>)requestparametersVariable[0];
        parameters = requestparametersVariable[1];
        if ((((market.ContainsKey("contract") ? market["contract"] : null) as bool?) == true))
        {
            Dictionary<string, object> responseRaw = await this.swapPublicGetV3MarketCandles(this.extend(request, parameters));
            //
            //     {
            //         code: "200",
            //         msg: "Success",
            //         data: [
            //           [
            //             "84207.02",
            //             "84320.85",
            //             "84207.02",
            //             "84253.83",
            //             "3707.5395",
            //             "44",
            //             "14",
            //             "1740770040000",
            //             "1740770099999",
            //           ],
            //
            List<object> data = this.safeList(responseRaw, "data");
            return ccxt.BaseExchange.ToOHLCVList(this.parseOHLCVs(data, market,timeframeVar, since, limit));
        }
        List<object> response = await this.publicGetMarketsSymbolCandles(this.extend(request, parameters));
        //
        //     [
        //         [
        //             "22814.01",
        //             "22937.42",
        //             "22832.57",
        //             "22937.42",
        //             "3916.58764051",
        //             "0.171199",
        //             "2982.64647063",
        //             "0.130295",
        //             33,
        //             0,
        //             "22877.449915304470460711",
        //             "MINUTE_5",
        //             1659664800000,
        //             1659665099999
        //         ]
        //     ]
        //
        List<object> candles = new List<object>() {};
        if (((response is IList<object>) || (response.GetType().IsGenericType && response.GetType().GetGenericTypeDefinition().IsAssignableFrom(typeof(List<>)))))
        {
            candles = response;
        }
        return ccxt.BaseExchange.ToOHLCVList(this.parseOHLCVs(candles, market,timeframeVar, since, limit));
    }

    public async override Task<IDictionary<string, object>> loadMarkets(object reload = null, object parameters = null)
    {
        reload ??= false;
        parameters ??= new Dictionary<string, object>();
        object markets = await base.loadMarkets(reload, parameters);
        IDictionary<string, object> currenciesByNumericId = this.safeDict(this.options, "currenciesByNumericId");
        if (((currenciesByNumericId == null)) || isTrue(reload))
        {
            this.options["currenciesByNumericId"] = this.indexBy(this.currencies, "numericId");
        }
        return ((IDictionary<string, object>)((object)(markets)));
    }

    /**
     * @method
     * @name poloniex#fetchMarkets
     * @description retrieves data on all markets for poloniex
     * @see https://api-docs.poloniex.com/spot/api/public/reference-data#symbol-information
     * @see https://api-docs.poloniex.com/v3/futures/api/market/get-all-product-info
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> promises = new List<object> {this.FetchSpotMarkets(parameters), this.FetchSwapMarkets(parameters)};
        List<object> results = await promiseAll(promises);
        return ccxt.BaseExchange.ToMarketInterfaceList(this.arrayConcat((results != null && 0 < results.Count ? results[0] : null), (results != null && 1 < results.Count ? results[1] : null)));
    }

