    public override Dictionary<string, object> parseMarket(object market)
    {
        if ((market != null && ((IDictionary<string, object>)market).ContainsKey("ctType")))
        {
            return ccxt.BaseExchange.ToDict(this.parseSwapMarket(market));
        } else
        {
            return ccxt.BaseExchange.ToDict(this.parseSpotMarket(market));
        }
    }

    public virtual Dictionary<string, object> parseSpotMarket(object market)
    {
        string? id = this.safeString(market, "symbol");
        string? baseId = this.safeString(market, "baseCurrencyName");
        string? quoteId = this.safeString(market, "quoteCurrencyName");
        string? bs = this.safeCurrencyCode(baseId);
        string? quote = this.safeCurrencyCode(quoteId);
        if (((bs == null)) || ((quote == null)))
        {
            return ((Dictionary<string, object>)((object)(null)));
        }
        string? state = this.safeString(market, "state");
        bool active = state == "NORMAL";
        IDictionary<string, object> symbolTradeLimit = this.safeDict(market, "symbolTradeLimit");
        // these are known defaults
        return this.safeMarketStructure(new Dictionary<string, object>() {
            { "id", id },
            { "symbol", ((bs + "/") + quote) },
            { "base", bs },
            { "quote", quote },
            { "settle", null },
            { "baseId", baseId },
            { "quoteId", quoteId },
            { "settleId", null },
            { "type", "spot" },
            { "spot", true },
            { "margin", false },
            { "swap", false },
            { "future", false },
            { "option", false },
            { "active", active },
            { "contract", false },
            { "linear", null },
            { "inverse", null },
            { "contractSize", null },
            { "expiry", null },
            { "expiryDatetime", null },
            { "strike", null },
            { "optionType", null },
            { "precision", new Dictionary<string, object>() {
                { "amount", this.parseNumber(this.parsePrecision(this.safeString(symbolTradeLimit, "quantityScale"))) },
                { "price", this.parseNumber(this.parsePrecision(this.safeString(symbolTradeLimit, "priceScale"))) },
            } },
            { "limits", new Dictionary<string, object>() {
                { "amount", new Dictionary<string, object>() {
                    { "min", this.safeNumber(symbolTradeLimit, "minQuantity") },
                    { "max", null },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", this.safeNumber(symbolTradeLimit, "minAmount") },
                    { "max", null },
                } },
            } },
            { "created", this.safeInteger(market, "tradableStartTime") },
            { "info", market },
        });
    }

    public virtual Dictionary<string, object> parseSwapMarket(object market)
    {
        //
        //            {
        //                "symbol": "BNB_USDT_PERP",
        //                "bAsset": ".PBNBUSDT",
        //                "bCcy": "BNB",
        //                "qCcy": "USDT",
        //                "visibleStartTime": "1620390600000",
        //                "tradableStartTime": "1620390600000",
        //                "sCcy": "USDT",
        //                "tSz": "0.001",
        //                "pxScale": "0.001,0.01,0.1,1,10",
        //                "lotSz": "1",
        //                "minSz": "1",
        //                "ctVal": "0.1",
        //                "status": "OPEN",
        //                "oDate": "1620287590000",
        //                "maxPx": "1000000",
        //                "minPx": "0.001",
        //                "maxQty": "1000000",
        //                "minQty": "1",
        //                "maxLever": "50",
        //                "lever": "10",
        //                "ctType": "LINEAR",
        //                "alias": "",
        //                "iM": "0.02",
        //                "mM": "0.0115",
        //                "mR": "2000",
        //                "buyLmt": "",
        //                "sellLmt": "",
        //                "ordPxRange": "0.05",
        //                "marketMaxQty": "2800",
        //                "limitMaxQty": "1000000"
        //            },
        //
        string? id = this.safeString(market, "symbol");
        string? baseId = this.safeString(market, "bCcy");
        string? quoteId = this.safeString(market, "qCcy");
        string? settleId = this.safeString(market, "sCcy");
        string? bs = this.safeCurrencyCode(baseId);
        string? quote = this.safeCurrencyCode(quoteId);
        if (((bs == null)) || ((quote == null)))
        {
            return ((Dictionary<string, object>)((object)(null)));
        }
        string? settle = this.safeCurrencyCode(settleId);
        string? status = this.safeString(market, "status");
        bool active = status == "OPEN";
        bool linear = (this.safeString(market, "ctType") == "LINEAR");
        string symbol = ((bs + "/") + quote);
        if (linear)
        {
            symbol = symbol + (":" + settle);
        } else
        {
            // actually, exchange does not have any inverse future now
            symbol = symbol + (":" + bs);
        }
        string? alias = this.safeString(market, "alias");
        string type = "swap";
        if ((alias != null))
        {
            type = "future";
        }
        string marketType = "swap";
        if (type == "future")
        {
            marketType = "future";
        }
        return this.safeMarketStructure(new Dictionary<string, object>() {
            { "id", id },
            { "symbol", symbol },
            { "base", bs },
            { "quote", quote },
            { "settle", settle },
            { "baseId", baseId },
            { "quoteId", quoteId },
            { "settleId", settleId },
            { "type", marketType },
            { "spot", false },
            { "margin", false },
            { "swap", type == "swap" },
            { "future", type == "future" },
            { "option", false },
            { "active", active },
            { "contract", true },
            { "linear", linear },
            { "inverse", !linear },
            { "contractSize", this.safeNumber(market, "ctVal") },
            { "expiry", null },
            { "expiryDatetime", null },
            { "strike", null },
            { "optionType", null },
            { "taker", this.safeNumber(market, "tFee") },
            { "maker", this.safeNumber(market, "mFee") },
            { "precision", new Dictionary<string, object>() {
                { "amount", this.safeNumber(market, "lotSz") },
                { "price", this.safeNumber(market, "tSz") },
            } },
            { "limits", new Dictionary<string, object>() {
                { "amount", new Dictionary<string, object>() {
                    { "min", this.safeNumber(market, "minSz") },
                    { "max", this.safeNumber(market, "limitMaxQty") },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", this.safeNumber(market, "minPx") },
                    { "max", this.safeNumber(market, "maxPx") },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "leverage", new Dictionary<string, object>() {
                    { "max", this.safeNumber(market, "maxLever") },
                    { "min", null },
                } },
            } },
            { "created", this.safeInteger(market, "oDate") },
            { "info", market },
        });
    }

