    public override Dictionary<string, object> parseTrade(object trade, object market = null)
    {
        //
        // fetchTrades
        //
        //  spot:
        //
        //     {
        //         "id" : "60014521",
        //         "price" : "23162.94",
        //         "quantity" : "0.00009",
        //         "amount" : "2.0846646",
        //         "takerSide" : "SELL",
        //         "ts" : 1659684602042,
        //         "createTime" : 1659684602036
        //     }
        //
        //   swap:
        //
        //     {
        //         "id": "105807376",
        //         "side": "buy",
        //         "px": "84410.57",
        //         "qty": "1",
        //         "amt": "84.41057",
        //         "cT": "1740777563557",
        //     }
        //
        // fetchMyTrades
        //
        //  spot:
        //
        //     {
        //         "id": "32164924331503616",
        //         "symbol": "LINK_USDT",
        //         "accountType": "SPOT",
        //         "orderId": "32164923987566592",
        //         "side": "SELL",
        //         "type": "MARKET",
        //         "matchRole": "TAKER",
        //         "createTime": 1648635115525,
        //         "price": "11",
        //         "quantity": "0.5",
        //         "amount": "5.5",
        //         "feeCurrency": "USDT",
        //         "feeAmount": "0.007975",
        //         "pageId": "32164924331503616",
        //         "clientOrderId": "myOwnId-321"
        //     }
        //
        //  swap:
        //
        //     {
        //         "symbol": "BTC_USDT_PERP",
        //         "trdId": "105813553",
        //         "side": "SELL",
        //         "type": "TRADE",
        //         "mgnMode": "CROSS",
        //         "ordType": "MARKET",
        //         "clOrdId": "polo418912106147315112",
        //         "role": "TAKER",
        //         "px": "84704.9",
        //         "qty": "1",
        //         "cTime": "1740842829430",
        //         "uTime": "1740842829450",
        //         "feeCcy": "USDT",
        //         "feeAmt": "0.04235245",
        //         "deductCcy": "",
        //         "deductAmt": "0",
        //         "feeRate": "0.0005",
        //         "id": "418912106342654592",
        //         "posSide": "BOTH",
        //         "ordId": "418912106147315112",
        //         "qCcy": "USDT",
        //         "value": "84.7049",
        //         "actType": "TRADING"
        //     },
        //
        // fetchOrderTrades (taker trades)
        //
        //     {
        //         "id": "30341456333942784",
        //         "symbol": "LINK_USDT",
        //         "accountType": "SPOT",
        //         "orderId": "30249408733945856",
        //         "side": "BUY",
        //         "type": "LIMIT",
        //         "matchRole": "MAKER",
        //         "createTime": 1648200366864,
        //         "price": "3.1",
        //         "quantity": "1",
        //         "amount": "3.1",
        //         "feeCurrency": "LINK",
        //         "feeAmount": "0.00145",
        //         "pageId": "30341456333942784",
        //         "clientOrderId": ""
        //     }
        //
        string? id = this.safeStringN(trade, new List<object>() {"id", "tradeID", "trdId"});
        string? orderId = this.safeString2(trade, "orderId", "ordId");
        Int64? timestamp = this.safeIntegerN(trade, new List<object>() {"ts", "createTime", "cT", "cTime"});
        string? marketId = this.safeString(trade, "symbol");
        market = this.safeMarket(marketId, market, "_");
        string? symbol = ((string)getValue(market, "symbol"));
        string? side = this.safeStringLower2(trade, "side", "takerSide");
        Dictionary<string, object> fee = null;
        string? priceString = this.safeString2(trade, "price", "px");
        string? amountString = this.safeString2(trade, "quantity", "qty");
        string? costString = this.safeString2(trade, "amount", "amt");
        string? feeCurrencyId = this.safeString2(trade, "feeCurrency", "feeCcy");
        string? feeCostString = this.safeString2(trade, "feeAmount", "feeAmt");
        if ((feeCostString != null))
        {
            string? feeCurrencyCode = this.safeCurrencyCode(feeCurrencyId);
            fee = new Dictionary<string, object>() {
                { "cost", feeCostString },
                { "currency", feeCurrencyCode },
            };
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "id", id },
            { "info", trade },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "symbol", symbol },
            { "order", orderId },
            { "type", this.safeStringLower2(trade, "ordType", "type") },
            { "side", side },
            { "takerOrMaker", this.safeStringLower2(trade, "matchRole", "role") },
            { "price", priceString },
            { "amount", amountString },
            { "cost", costString },
            { "fee", fee },
        }, market);
    }

    /**
     * @method
     * @name poloniex#fetchTrades
     * @description get the list of most recent trades for a particular symbol
     * @see https://api-docs.poloniex.com/spot/api/public/market-data#trades
     * @see https://api-docs.poloniex.com/v3/futures/api/market/get-execution-info
     * @param {string} symbol unified symbol of the market to fetch trades for
     * @param {int} [since] timestamp in ms of the earliest trade to fetch
     * @param {int} [limit] the maximum amount of trades to fetch
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=public-trades}
     */
    public async override Task<List<ccxt.Trade>> FetchTrades(string symbol, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "symbol", (market.ContainsKey("id") ? market["id"] : null) },
        };
        if ((limit != null))
        {
            request["limit"] = limit; // max 1000, for spot & swap
        }
        if ((((market.ContainsKey("contract") ? market["contract"] : null) as bool?) == true))
        {
            Dictionary<string, object> response = await this.swapPublicGetV3MarketTrades(this.extend(request, parameters));
            //
            //     {
            //         code: "200",
            //         msg: "Success",
            //         data: [
            //         {
            //             id: "105807320", // descending order
            //             side: "sell",
            //             px: "84383.93",
            //             qty: "1",
            //             amt: "84.38393",
            //             cT: "1740777074704",
            //         },
            //
            List<object> tradesList = this.safeList(response, "data", new List<object>() {});
            return ccxt.BaseExchange.ToTradeList(this.parseTrades(tradesList, market, since, limit));
        }
        List<object> trades = await this.publicGetMarketsSymbolTrades(this.extend(request, parameters));
        //
        //     [
        //         {
        //             "id" : "60014521",
        //             "price" : "23162.94",
        //             "quantity" : "0.00009",
        //             "amount" : "2.0846646",
        //             "takerSide" : "SELL",
        //             "ts" : 1659684602042,
        //             "createTime" : 1659684602036
        //         }
        //     ]
        //
        return ccxt.BaseExchange.ToTradeList(this.parseTrades(trades, market, since, limit));
    }

    /**
     * @method
     * @name poloniex#fetchMyTrades
     * @description fetch all trades made by the user
     * @see https://api-docs.poloniex.com/spot/api/private/trade#trade-history
     * @see https://api-docs.poloniex.com/v3/futures/api/trade/get-execution-details
     * @param {string} symbol unified market symbol
     * @param {int} [since] the earliest time in ms to fetch trades for
     * @param {int} [limit] the maximum number of trades structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {int} [params.until] the latest time in ms to fetch entries for
     * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
     * @returns {Trade[]} a list of [trade structures]{@link https://docs.ccxt.com/?id=trade-structure}
     */
    public async override Task<List<ccxt.Trade>> FetchMyTrades(string symbol = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        bool? paginate = false;
        IList<object> paginateparametersVariable = (IList<object>)this.handleOptionBoolAndParams(parameters, "fetchMyTrades", "paginate", false);
        paginate = (bool?)paginateparametersVariable[0];
        parameters = paginateparametersVariable[1];
        if ((paginate == true))
        {
            return ccxt.BaseExchange.ToTradeList(await this.fetchPaginatedCallDynamic("fetchMyTrades", symbol, since, limit, parameters));
        }
        IDictionary<string, object> market = null;
        if ((symbol != null))
        {
            market = this.market(symbol);
        }
        string? marketType = null;
        IList<object> marketTypeparametersVariable = (IList<object>)this.handleMarketTypeAndParams("fetchMyTrades", market, parameters);
        marketType = (string)marketTypeparametersVariable[0];
        parameters = marketTypeparametersVariable[1];
        bool isContract = this.inArray(marketType, new List<object>() {"swap", "future"});
        Dictionary<string, object> request = new Dictionary<string, object>() {};
        string startKey = "startTime";
        if (isContract)
        {
            startKey = "sTime";
        }
        string endKey = "endTime";
        if (isContract)
        {
            endKey = "eTime";
        }
        if ((since != null))
        {
            request[(string)startKey] = since;
        }
        if ((limit != null))
        {
            request["limit"] = limit;
        }
        if (isContract && (symbol != null))
        {
            request["symbol"] = this.safeString(market, "id");
        }
        IList<object> requestparametersVariable = (IList<object>)this.handleUntilOption(endKey, request, parameters);
        request = (Dictionary<string, object>)requestparametersVariable[0];
        parameters = requestparametersVariable[1];
        if (isContract)
        {
            Dictionary<string, object> raw = await this.swapPrivateGetV3TradeOrderTrades(this.extend(request, parameters));
            //
            //    {
            //        "code": "200",
            //        "msg": "",
            //        "data": [
            //            {
            //                "symbol": "BTC_USDT_PERP",
            //                "trdId": "105813553",
            //                "side": "SELL",
            //                "type": "TRADE",
            //                "mgnMode": "CROSS",
            //                "ordType": "MARKET",
            //                "clOrdId": "polo418912106147315112",
            //                "role": "TAKER",
            //                "px": "84704.9",
            //                "qty": "1",
            //                "cTime": "1740842829430",
            //                "uTime": "1740842829450",
            //                "feeCcy": "USDT",
            //                "feeAmt": "0.04235245",
            //                "deductCcy": "",
            //                "deductAmt": "0",
            //                "feeRate": "0.0005",
            //                "id": "418912106342654592",
            //                "posSide": "BOTH",
            //                "ordId": "418912106147315112",
            //                "qCcy": "USDT",
            //                "value": "84.7049",
            //                "actType": "TRADING"
            //            },
            //
            List<object> data = this.safeList(raw, "data", new List<object>() {});
            return ccxt.BaseExchange.ToTradeList(this.parseTrades(data, market, since, limit));
        }
        List<object> response = await this.privateGetTrades(this.extend(request, parameters));
        //
        //     [
        //         {
        //             "id": "32164924331503616",
        //             "symbol": "LINK_USDT",
        //             "accountType": "SPOT",
        //             "orderId": "32164923987566592",
        //             "side": "SELL",
        //             "type": "MARKET",
        //             "matchRole": "TAKER",
        //             "createTime": 1648635115525,
        //             "price": "11",
        //             "quantity": "0.5",
        //             "amount": "5.5",
        //             "feeCurrency": "USDT",
        //             "feeAmount": "0.007975",
        //             "pageId": "32164924331503616",
        //             "clientOrderId": "myOwnId-321"
        //         }
        //     ]
        //
        IList<object> result = this.parseTrades(response, market, since, limit);
        return ccxt.BaseExchange.ToTradeList(result);
    }

    public virtual string? parseOrderStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "NEW", "open" },
            { "PARTIALLY_FILLED", "open" },
            { "FILLED", "closed" },
            { "PENDING_CANCEL", "canceled" },
            { "PARTIALLY_CANCELED", "canceled" },
            { "CANCELED", "canceled" },
            { "FAILED", "canceled" },
        };
        return this.safeString(statuses, status, status);
    }

    public override Dictionary<string, object> parseOrder(object order, IDictionary<string, object> market = null)
    {
        //
        // fetchOpenOrder
        //
        //     {
        //         "id" : "7xxxxxxxxxxxxxxx6",
        //         "clientOrderId" : "",
        //         "symbol" : "ETH_USDT",
        //         "state" : "NEW",
        //         "accountType" : "SPOT",
        //         "side" : "BUY",
        //         "type" : "LIMIT",
        //         "timeInForce" : "GTC",
        //         "quantity" : "0.001",
        //         "price" : "1600",
        //         "avgPrice" : "0",
        //         "amount" : "0",
        //         "filledQuantity" : "0",
        //         "filledAmount" : "0",
        //         "createTime" : 16xxxxxxxxx26,
        //         "updateTime" : 16xxxxxxxxx36
        //     }
        //
        // fetchOpenOrders (and fetchClosedOrders same for contracts)
        //
        //  spot:
        //
        //     {
        //         "id": "24993088082542592",
        //         "clientOrderId": "",
        //         "symbol": "ELON_USDC",
        //         "state": "NEW",
        //         "accountType": "SPOT",
        //         "side": "SELL",
        //         "type": "MARKET",
        //         "timeInForce": "GTC",
        //         "quantity": "1.00",
        //         "price": "0.00",
        //         "avgPrice": "0.00",
        //         "amount": "0.00",
        //         "filledQuantity": "0.00",
        //         "filledAmount": "0.00",
        //         "createTime": 1646925216548,
        //         "updateTime": 1646925216548
        //     }
        //
        //  contract:
        //
        //     {
        //         "symbol": "BTC_USDT_PERP",
        //         "side": "BUY",
        //         "type": "LIMIT",
        //         "ordId": "418890767248232148",
        //         "clOrdId": "polo418890767248232148",
        //         "mgnMode": "CROSS",
        //         "px": "81130.13",
        //         "reduceOnly": false,
        //         "lever": "20",
        //         "state": "NEW",
        //         "source": "WEB",
        //         "timeInForce": "GTC",
        //         "tpTrgPx": "",
        //         "tpPx": "",
        //         "tpTrgPxType": "",
        //         "slTrgPx": "",
        //         "slPx": "",
        //         "slTrgPxType": "",
        //         "avgPx": "0",
        //         "execQty": "0",
        //         "execAmt": "0",
        //         "feeCcy": "",
        //         "feeAmt": "0",
        //         "deductCcy": "0",
        //         "deductAmt": "0",
        //         "stpMode": "NONE", // todo: selfTradePrevention
        //         "cTime": "1740837741523",
        //         "uTime": "1740840846882",
        //         "sz": "1",
        //         "posSide": "BOTH",
        //         "qCcy": "USDT"
        //         "cancelReason": "", // this field can only be in closed orders
        //     },
        //
        // createOrder, editOrder
        //
        //  spot:
        //
        //     {
        //         "id": "29772698821328896",
        //         "clientOrderId": "1234Abc"
        //     }
        //
        //  contract:
        //
        //    {
        //        "ordId":"418876147745775616",
        //        "clOrdId":"polo418876147745775616"
        //    }
        //
        Int64? timestamp = this.safeIntegerN(order, new List<object>() {"timestamp", "createTime", "cTime"});
        if ((timestamp == null))
        {
            timestamp = this.parse8601(this.safeString(order, "date"));
        }
        string? marketId = this.safeString(order, "symbol");
        market = this.safeMarket(marketId, market, "_");
        string? symbol = ((string)(market != null && market.ContainsKey("symbol") ? market["symbol"] : null));
        object resultingTrades = this.safeValue(order, "resultingTrades");
        if ((resultingTrades != null))
        {
            if (!((resultingTrades is IList<object>) || (resultingTrades.GetType().IsGenericType && resultingTrades.GetType().GetGenericTypeDefinition().IsAssignableFrom(typeof(List<>)))))
            {
                resultingTrades = this.safeValue(resultingTrades, this.safeString(market, "id", marketId));
            }
        }
        string? price = this.safeStringN(order, new List<object>() {"price", "rate", "px"});
        string? amount = this.safeString2(order, "quantity", "sz");
        string? filled = this.safeString2(order, "filledQuantity", "execQty");
        string? status = this.parseOrderStatus(this.safeString(order, "state"));
        string? side = this.safeStringLower(order, "side");
        string? rawType = this.safeString(order, "type");
        string? type = this.parseOrderType(rawType);
        string? id = this.safeStringN(order, new List<object>() {"orderNumber", "id", "orderId", "ordId"});
        Dictionary<string, object> fee = null;
        string? feeCurrency = this.safeString2(order, "tokenFeeCurrency", "feeCcy");
        string? feeCost = null;
        object feeCurrencyCode = null;
        string? rate = this.safeString(order, "fee");
        if ((feeCurrency == null))
        {
            feeCurrencyCode = (side == "buy") ? (market != null && market.ContainsKey("base") ? market["base"] : null) : (market != null && market.ContainsKey("quote") ? market["quote"] : null);
        } else
        {
            // poloniex accepts a 30% discount to pay fees in TRX
            feeCurrencyCode = this.safeCurrencyCode(feeCurrency);
            feeCost = this.safeString2(order, "tokenFee", "feeAmt");
        }
        if ((feeCost != null))
        {
            fee = new Dictionary<string, object>() {
                { "rate", rate },
                { "cost", feeCost },
                { "currency", feeCurrencyCode },
            };
        }
        string? clientOrderId = this.safeString2(order, "clientOrderId", "clOrdId");
        string? marginMode = this.safeStringLower(order, "mgnMode");
        bool? reduceOnly = this.safeBool(order, "reduceOnly");
        Int64? leverage = this.safeInteger(order, "lever");
        bool hedged = (this.safeString(order, "posSide") != "BOTH");
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "id", id },
            { "clientOrderId", clientOrderId },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", this.safeInteger(order, "updateTime") },
            { "status", status },
            { "symbol", symbol },
            { "type", type },
            { "timeInForce", this.safeString(order, "timeInForce") },
            { "postOnly", rawType == "LIMIT_MAKER" },
            { "side", side },
            { "price", price },
            { "triggerPrice", this.safeString2(order, "triggerPrice", "stopPrice") },
            { "cost", this.safeString(order, "execAmt") },
            { "average", this.safeString2(order, "avgPrice", "avgPx") },
            { "amount", amount },
            { "filled", filled },
            { "remaining", null },
            { "trades", resultingTrades },
            { "fee", fee },
            { "marginMode", marginMode },
            { "reduceOnly", reduceOnly },
            { "leverage", leverage },
            { "hedged", hedged },
        }, market);
    }

    public virtual string? parseOrderType(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "MARKET", "market" },
            { "LIMIT", "limit" },
            { "LIMIT_MAKER", "limit" },
            { "STOP-LIMIT", "limit" },
            { "STOP-MARKET", "market" },
        };
        return this.safeString(statuses, status, status);
    }

    public virtual object parseOpenOrders(object orders, IDictionary<string, object> market, object result)
    {
        for (int i = 0; i < getArrayLength(orders); i++)
        {
            IDictionary<string, object> order = ((IDictionary<string, object>)getValue(orders, i));
            Dictionary<string, object> extended = this.extend(order, new Dictionary<string, object>() {
                { "status", "open" },
                { "type", "limit" },
                { "side", (order != null && ((IDictionary<string, object>)order).ContainsKey("type") ? ((IDictionary<string, object>)order)["type"] : null) },
                { "price", (order != null && ((IDictionary<string, object>)order).ContainsKey("rate") ? ((IDictionary<string, object>)order)["rate"] : null) },
            });
            ((IList<object>)result).Add(this.parseOrder(extended, market));
        }
        return result;
    }

