     */
    public async override Task<List<ccxt.Transaction>> FetchDeposits(string code = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = ccxt.BaseExchange.FromDict(await this.FetchTransactionsHelper(code, since, limit, parameters));
        IDictionary<string, object> currency = null;
        if ((code != null))
        {
            currency = this.currency(code);
        }
        List<object> deposits = this.safeList(response, "deposits", new List<object>() {});
        IList<object> transactions = this.parseTransactions(deposits, currency, since, limit);
        return ccxt.BaseExchange.ToTransactionList(this.filterByCurrencySinceLimit(transactions,code, since, limit));
    }

    public virtual string? parseTransactionStatus(object status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "COMPLETE", "ok" },
            { "COMPLETED", "ok" },
            { "AWAITING APPROVAL", "pending" },
            { "AWAITING_APPROVAL", "pending" },
            { "PENDING", "pending" },
            { "PROCESSING", "pending" },
            { "COMPLETE ERROR", "failed" },
            { "COMPLETE_ERROR", "failed" },
        };
        return this.safeString(statuses, ((string)status), status);
    }

    public override Dictionary<string, object> parseTransaction(object transaction, object currency = null)
    {
        //
        // deposits
        //
        //     {
        //         "txid": "f49d489616911db44b740612d19464521179c76ebe9021af85b6de1e2f8d68cd",
        //         "amount": "49798.01987021",
        //         "status": "COMPLETE",
        //         "address": "DJVJZ58tJC8UeUv9Tqcdtn6uhWobouxFLT",
        //         "currency": "DOGE",
        //         "timestamp": 1524321838,
        //         "confirmations": 3371,
        //         "depositNumber": 134587098
        //     }
        //
        // withdrawals
        //
        //     {
        //         "withdrawalRequestsId": 7397527,
        //         "currency": "ETC",
        //         "address": "0x26419a62055af459d2cd69bb7392f5100b75e304",
        //         "amount": "13.19951600",
        //         "fee": "0.01000000",
        //         "timestamp": 1506010932,
        //         "status": "COMPLETED",
        //         "txid": "343346392f82ac16e8c2604f2a604b7b2382d0e9d8030f673821f8de4b5f5bk",
        //         "ipAddress": "1.2.3.4",
        //         "paymentID": null
        //     }
        //
        // withdraw
        //
        //     {
        //         "withdrawalRequestsId": 33485231
        //     }
        //
        // if it's being parsed from "withdraw()" method, get the original response
        if ((transaction != null && ((IDictionary<string, object>)transaction).ContainsKey("withdrawNetworkEntry")))
        {
            transaction = getValue(transaction, "response");
        }
        Int64? timestamp = this.safeTimestamp(transaction, "timestamp");
        string? currencyId = this.safeString(transaction, "currency");
        string? code = this.safeCurrencyCode(currencyId);
        string? status = this.safeString(transaction, "status", "pending");
        status = this.parseTransactionStatus(status);
        string? txid = this.safeString(transaction, "txid");
        string type = "deposit";
        if (inOp(transaction, "withdrawalRequestsId"))
        {
            type = "withdrawal";
        }
        string? id = this.safeString2(transaction, "withdrawalRequestsId", "depositNumber");
        string? address = this.safeString(transaction, "address");
        string? tag = this.safeString(transaction, "paymentID");
        string? amountString = this.safeString(transaction, "amount");
        string? feeCostString = this.safeString(transaction, "fee");
        if (type == "withdrawal")
        {
            amountString = Precise.stringSub(amountString, feeCostString);
        }
        return new Dictionary<string, object>() {
            { "info", transaction },
            { "id", id },
            { "currency", code },
            { "amount", this.parseNumber(amountString) },
            { "network", null },
            { "address", address },
            { "addressTo", null },
            { "addressFrom", null },
            { "tag", tag },
            { "tagTo", null },
            { "tagFrom", null },
            { "status", status },
            { "type", type },
            { "updated", null },
            { "txid", txid },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "comment", null },
            { "internal", null },
            { "fee", new Dictionary<string, object>() {
                { "currency", code },
                { "cost", this.parseNumber(feeCostString) },
                { "rate", null },
            } },
        };
    }

    /**
     * @method
     * @name poloniex#setLeverage
     * @description set the level of leverage for a market
     * @see https://api-docs.poloniex.com/v3/futures/api/positions/set-leverage
     * @param {int} leverage the rate of leverage
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @param {string} [params.marginMode] 'cross' or 'isolated'
     * @returns {object} response from the exchange
     */
    public async override Task<Dictionary<string, object>> SetLeverage(object leverage, string symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((symbol == null))
        {
            throw new ArgumentsRequired ((this.id + " setLeverage() requires a symbol argument")) ;
        }
        await this.loadMarkets();
        Dictionary<string, object> market = this.market(symbol);
        string? marginMode = null;
        IList<object> marginModeparametersVariable = (IList<object>)this.handleMarginModeAndParams("setLeverage", parameters);
        marginMode = (string)marginModeparametersVariable[0];
        parameters = marginModeparametersVariable[1];
        if ((marginMode == null))
        {
            throw new ArgumentsRequired ((this.id + " setLeverage() requires a marginMode parameter \"cross\" or \"isolated\"")) ;
        }
        bool? hedged = null;
        IList<object> hedgedparametersVariable = (IList<object>)this.handleParamBool(parameters, "hedged", false);
        hedged = (bool?)hedgedparametersVariable[0];
        parameters = hedgedparametersVariable[1];
        if ((hedged == true))
        {
            if (!(((IDictionary<string, object>)parameters).ContainsKey("posSide")))
            {
                throw new ArgumentsRequired ((this.id + " setLeverage() requires a posSide parameter for hedged mode: \"LONG\" or \"SHORT\"")) ;
            }
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "lever", leverage },
            { "mgnMode", marginMode.ToUpper() },
            { "symbol", (market.ContainsKey("id") ? market["id"] : null) },
        };
        Dictionary<string, object> response = await this.swapPrivatePostV3PositionLeverage(this.extend(request, parameters));
        return ccxt.BaseExchange.ToDict(response);
    }

    /**
     * @method
     * @name poloniex#fetchLeverage
     * @description fetch the set leverage for a market
     * @see https://api-docs.poloniex.com/v3/futures/api/positions/get-leverages
     * @param {string} symbol unified market symbol
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [leverage structure]{@link https://docs.ccxt.com/?id=leverage-structure}
     */
    public async override Task<ccxt.Leverage> FetchLeverage(string symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        await this.loadMarkets();
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "symbol", (market.ContainsKey("id") ? market["id"] : null) },
        };
        string? marginMode = null;
        IList<object> marginModeparametersVariable = (IList<object>)this.handleMarginModeAndParams("fetchLeverage", parameters);
        marginMode = (string)marginModeparametersVariable[0];
        parameters = marginModeparametersVariable[1];
        if ((marginMode == null))
        {
            throw new ArgumentsRequired ((this.id + " fetchLeverage() requires a marginMode parameter \"cross\" or \"isolated\"")) ;
        }
        request["mgnMode"] = marginMode.ToUpper();
        Dictionary<string, object> response = await this.swapPrivateGetV3PositionLeverages(this.extend(request, parameters));
        //
        //  for one-way mode:
        //
        //    {
        //        "code": "200",
        //        "msg": "",
        //        "data": [
        //            {
        //                "symbol": "BTC_USDT_PERP",
        //                "lever": "10",
        //                "mgnMode": "CROSS",
        //                "posSide": "BOTH"
        //            }
        //        ]
        //    }
        //
        //  for hedge:
        //
        //    {
        //        "code": "200",
        //        "msg": "",
        //        "data": [
        //            {
        //                "symbol": "BTC_USDT_PERP",
        //                "lever": "20",
        //                "mgnMode": "CROSS",
        //                "posSide": "SHORT"
        //            },
        //            {
        //                "symbol": "BTC_USDT_PERP",
        //                "lever": "20",
        //                "mgnMode": "CROSS",
        //                "posSide": "LONG"
        //            }
        //        ]
        //    }
        //
        return ccxt.BaseExchange.ToLeverage(this.parseLeverage(response, market));
    }

    public override Dictionary<string, object> parseLeverage(object leverage, IDictionary<string, object> market = null)
    {
        Int64? shortLeverage = null;
        Int64? longLeverage = null;
        string? marketId = null;
        string? marginMode = null;
        List<object> data = this.safeList(leverage, "data", new List<object>() {});
        for (int i = 0; i < data.Count; i++)
        {
            IDictionary<string, object> entry = this.safeDict(data, i);
            marketId = this.safeString(entry, "symbol");
            // mgnMode arrives upper case; parseOrder and parsePosition read the
            // same field with safeStringLower
            marginMode = this.safeStringLower(entry, "mgnMode");
            Int64? lever = this.safeInteger(entry, "lever");
            string? posSide = this.safeString(entry, "posSide");
            if (posSide == "LONG")
            {
                longLeverage = lever;
            } else if (posSide == "SHORT")
            {
                shortLeverage = lever;
            } else
            {
                longLeverage = lever;
                shortLeverage = lever;
            }
        }
        return new Dictionary<string, object>() {
            { "info", leverage },
            { "symbol", this.safeSymbol(marketId, market) },
            { "marginMode", marginMode },
            { "longLeverage", longLeverage },
            { "shortLeverage", shortLeverage },
        };
    }

    /**
     * @method
     * @name poloniex#fetchPositionMode
     * @description fetches the position mode, hedged or one way, hedged is set identically for all linear markets or all inverse markets
     * @see https://api-docs.poloniex.com/v3/futures/api/positions/position-mode-switch
     * @param {string} [symbol] unified symbol of the market to fetch the position mode for (not used by fetchPositionMode)
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an object detailing whether the market is in hedged or one-way mode
     */
    public async override Task<ccxt.PositionModeInfo> FetchPositionMode(string symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = await this.swapPrivateGetV3PositionMode(parameters);
        //
        //    {
        //        "code": "200",
        //        "msg": "Success",
        //        "data": {
        //            "posMode": "ONE_WAY"
        //        }
        //    }
        //
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        string? posMode = this.safeString(data, "posMode");
        bool hedged = posMode == "HEDGE";
        return ccxt.BaseExchange.ToPositionModeInfo(new Dictionary<string, object>() {             { "info", response },             { "hedged", hedged },         });
    }

    /**
     * @method
     * @name poloniex#setPositionMode
     * @description set hedged to true or false for a market
     * @see https://api-docs.poloniex.com/v3/futures/api/positions/position-mode-switch
     * @param {bool} hedged set to true to use the hedged position mode
     * @param {string} symbol not used by setPositionMode ()
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} response from the exchange
     */
    public async override Task<Dictionary<string, object>> SetPositionMode(object hedged, string symbol = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        string mode = "ONE_WAY";
        if (isTrue(hedged))
        {
            mode = "HEDGE";
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "posMode", mode },
        };
        Dictionary<string, object> response = await this.swapPrivatePostV3PositionMode(this.extend(request, parameters));
        //
        //    {
        //        "code": "200",
        //        "msg": "Success",
        //        "data": {}
        //    }
        //
        return ccxt.BaseExchange.ToDict(response);
    }

